import{_ as s,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"DataMagic: Transforming Tabular Data into Data Insight Video","description":"","frontmatter":{"title":"DataMagic: Transforming Tabular Data into Data Insight Video","arxiv":"2606.20388","date":"2026-06-18","authors":"Yupeng Xie, Chen Ma, Zhenyang Wang, Liangwei Wang, Jiayi Zhu, Chuxuan Zeng, Zhouan Shen, Boyan Li, Yuyu Luo","categories":"cs.HC, cs.AI, cs.DB","topics":"数据视频生成, 声明式规范, 多智能体流水线","outline":[2,2]},"headers":[],"relativePath":"papers/2606.20388.md","filePath":"papers/2606.20388.md","lastUpdated":null}'),r={name:"papers/2606.20388.md"};function p(o,a,i,l,c,g){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="datamagic-transforming-tabular-data-into-data-insight-video" tabindex="-1">DataMagic: Transforming Tabular Data into Data Insight Video <a class="header-anchor" href="#datamagic-transforming-tabular-data-into-data-insight-video" aria-label="Permalink to &quot;DataMagic: Transforming Tabular Data into Data Insight Video&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.20388" target="_blank" rel="noreferrer">2606.20388</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-18</td></tr><tr><td><strong>作者</strong></td><td>Yupeng Xie, Chen Ma, Zhenyang Wang, Liangwei Wang, Jiayi Zhu, Chuxuan Zeng, Zhouan Shen, Boyan Li, Yuyu Luo</td></tr><tr><td><strong>分类</strong></td><td>cs.HC, cs.AI, cs.DB（VLDB 2026 接收，5 页 demo 论文）</td></tr><tr><td><strong>一句话</strong></td><td>不去生成像素，而是让多 agent 先并行产出候选场景、再全局编排叙事顺序，把结果写进一份把视觉元素绑定到数据字段、用旁白句索引触发动画的声明式规范 DVSpec，最后编译成视频。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>数据视频把动态图表、语音旁白和同步动画组合成时序叙事，是把数据洞察讲清楚的有效媒介。但做一支高质量数据视频要跨三个领域：数据分析、叙事设计、视频制作。论文指出现有路径没有一条能做到从原始数据到成片的端到端自动化。</p><p>对视频生成研究来说，这篇论文的价值不在它有多复杂，而在它选择的路线本身是一个<strong>反向论证</strong>：面对「把数据变成视频」这个任务，作者明确拒绝了像素级生成。理由说得很硬——Sora 这类模型的黑箱性质「frequently produces numerical hallucinations」，并且<strong>无法把视觉元素映射回底层数据记录</strong>。在一个错一个数字就等于全盘失效的场景里，统计意义上的保真度不够用，需要的是结构性的保真。这个判断值得所有做「agent + 视频生成」的人认真对待：不是所有视频都该由扩散模型采样出来。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>三类方法，三种失败方式，论文分得很干净。</p><p><strong>静态可视化工具</strong>（BI 仪表盘、HAIChart、DeepEye）输出的是静态图表，缺少叙事逻辑与动画。它们解决的是「画哪个图」，不解决「按什么顺序讲」。</p><p><strong>创作工具</strong>（Data Player、Data Playwright）专注于给<strong>已有图表</strong>加动画效果，前提是用户已经准备好可视化。它们既不从原始数据里抽洞察，也不处理多场景的叙事编排——把最难的两端都留给了用户。</p><p><strong>像素级视频生成模型</strong>（Sora 一类）能合成视频，但保证不了数据保真与溯源。</p><p><strong>声明式规范</strong>这条线（Vega-Lite、Canis、ChartMark）对静态图表或单图注释与动画表现良好，但<strong>没有扩展到多场景数据视频所需的跨模态内容统一描述与时序协调</strong>。这是 DVSpec 要填的空缺。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从已有事实出发：LLM 写 pandas 做聚合已经可用；Vega-Lite 一类的声明式图表语法已被证明是好的中间表示；数据溯源（provenance）在交互式可视化里早被确立为关键使能技术。</p><p>第一个自然想法是让 LLM 一次性把整支视频「写」出来。论文实际做了这个实验，结果是四个最强 LLM 的平均质量分只有 1.91–2.22（五分制），执行成功率 48–86%。失败模式被明确记录：<strong>音画时序错位</strong>与<strong>缺乏叙事结构</strong>——旁白与画面对不上，场景之间没有逻辑过渡。</p><p>这两个失败模式各自指向一个设计。时序错位的根源是：动画触发时间如果写成绝对时间戳，那么 TTS 合成出的音频长度一变（用户改一句旁白就会变），同步关系就全毁了。把触发时间改成<strong>旁白句索引</strong>、渲染时按实际音频时长对齐，同步就成了不变量。缺乏叙事结构的根源是：逐场景贪心生成时，模型在写第 3 个场景时并不知道第 5 个场景会讲什么。要做全局优化就必须先有候选池——于是「先并行生成候选、再全局编排」这个两阶段结构被逼出来。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>数据视频不是视觉元素的堆叠，而是<strong>结构化叙事</strong>。既然如此，就不要去生成像素，而是生成一份把每个视觉元素绑回数据字段、把每个动画绑回旁白句的规范，再把它编译成视频。保真度因此是结构性的而非统计性的，并且因为逻辑与渲染解耦，成片仍然可以被点击、被修改、被追问。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>用论文的演示场景走一遍：用户上传一份科技公司财报 CSV，输入「分析 Q4 营收峰值、各区域营销效率、以及利润贡献最高的产品」。</p><p><strong>阶段一：数据驱动的候选生成（并行）</strong>。Story Planner 按涉及的分析维度把查询拆成若干独立子任务（时间趋势、类别对比、区域分布）。对每个子任务，Data Manager 规划数据处理流程并<strong>自动生成 Python 代码</strong>去原表里抽取、过滤、聚合出数据切片。Visual Designer 设计可视化方案（图表类型、数据绑定、样式配置），抽出关键洞察，填进 DVSpec 的 content 字段。这一阶段产出的是一个候选场景池，低层数据处理与高层叙事构建在此解耦。</p><p><strong>阶段二：全局叙事编排</strong>。Narration Director 按洞察价值与查询覆盖度从候选池里<strong>选</strong>场景，再按叙事逻辑（宏观到微观、先现象后原因）排出播放顺序，并在生成每段旁白时以相邻场景为条件，保证转场连贯。Animation Coordinator 利用 DVSpec 的语义引用机制，把旁白里提到的数据实体绑定到对应的视觉元素上，实现端到端音画同步。</p><p><strong>渲染</strong>：DVSpec 编译成视频，旁白经 TTS 合成语音。当前实现用 D3.js 画图、Remotion 合成视频，但 DVSpec 本身与渲染库无关。</p><p><strong>交互</strong>：因为 DVSpec 记录了每个视觉与动画元素对应的数据字段与旁白段，任何修改都能被精确定位并局部应用，无需重生成整支视频。三种交互模式共享同一份 DVSpec 状态——画布直接操作（下拉切换柱状图为饼图、拖拽元素、双击改文字）、声明式脚本编辑（直接改旁白或动画参数）、自然语言指令（<code>@Scene 4: change to treemap and highlight top product</code>）。数据问答走的是<strong>结构化检索</strong>：LLM 解析问题 → 从当前场景的 DVSpec 绑定里定位相关数据字段 → 构造过滤/聚合/极值查询直接在原表上执行，而不是让视觉模型从像素里猜。用户还能把问答得到的洞察反手变成新场景插进视频，闭合「探索→叙事扩展」的环。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>DVSpec 的形式化很简洁：一支数据视频是元数据与有序场景序列的组合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mclose">)</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⟨</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">⟩</span></span></span></span>，每个场景是四元组</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord text"><span class="mord textit">type</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord textit">content</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord textit">narration</span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord textit">animation</span></span><span class="mclose">)</span></span></span></span></span></p><p>其中 content 描述可视化内容与数据绑定，narration 是有序的旁白段列表，animation 是动画效果列表。</p><p>真正承载论文核心机制的不是这个记号本身，而是两条绑定约束。<strong>数据驱动的语义引用</strong>要求视觉元素通过数据属性值来引用（<code>{&quot;company&quot;: &quot;Nvidia&quot;}</code>）而不是硬编码标识符，从而在数据更新或图表类型改变时引用仍然有效，且每个视觉元素都能精确回溯到底层表记录；大小写、空格这类细微命名差异在渲染时用模糊匹配消解。<strong>旁白索引式声明触发</strong>要求动画触发时间用旁白段索引声明而非绝对时间戳，渲染时按 TTS 实际生成的音频时长自动对齐——这使得「用户改旁白文字」与「动画同步关系」这两件事在设计上就被解耦，不需要手工调关键帧。</p><p>本文无形式化数学推导（无定理、无优化目标），上述记号是规范定义而非推导。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>当前 LLM 直接生成数据视频到底行不行？</strong> 在 DAComp-DA 与 T2R-bench 的 109 个真实样本上，用 DeepSeek-V3.2、Gemini-2.5-Pro、GPT-5、Claude-Sonnet-4 各自一次性生成。结果是平均质量分 1.91–2.22（五个维度 1–5 分：Intent Fulfillment、Data Insights、Narrative Quality、Animation Effectiveness、Aesthetic Quality），执行成功率 48–86%。主要问题就是前面说的音画错位与叙事无结构。</p><p><strong>DataMagic 提升多少？</strong> 平均分升到 3.89，执行率 95% 以上。增益最大的两项恰好对应两个设计动机：Animation Effectiveness 1.84 → 4.03（+120%），Narrative Quality 2.00 → 3.43（+72%）。评审用 Gemini-2.5-Pro 自动打分，与人类专家在 60 支采样视频上的 Pearson 相关系数为 0.91。</p><p><strong>代价是什么？</strong> 直接生成平均约 57 秒，DataMagic 约 176 秒（60 秒配置生成 + 116 秒渲染，并行度 3）。论文把这称为有意为之的质量-延迟权衡。</p><p><strong>两个组件缺一不可吗？</strong> 去掉 Story Planner，平均质量降 11.6%（叙事维度 −15.1%）；去掉 Orchestration，降 9.0%（意图维度 −12.4%）。两处消融各自打在自己负责的维度上，归因是自洽的。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：在数据视频这个「错一个数字就废掉」的场景里，作者明确拒绝像素级生成，理由是黑箱模型会产生数值幻觉且无法把画面映射回数据记录；替代方案是生成一份声明式规范 DVSpec，用数据属性值而非硬编码 ID 引用视觉元素、用旁白句索引而非绝对时间戳触发动画；多 agent 采用 Generate-then-Orchestrate 两段式，先并行产候选场景再全局优化选择、排序与叙事连贯，避免逐场景贪心；109 个真实样本上平均质量从最强 LLM 一次性生成的 2.22 提到 3.89、执行率从 48–86% 提到 95% 以上，动画有效性提升 120%；逻辑与渲染解耦带来的副产品是视频可点击可修改可追问，单向视频变成可探索的数据界面。</p><p><strong>3 句版</strong>：把数据视频当作可编译的声明式规范而不是可采样的像素序列，数据保真就从统计问题变成结构问题。多 agent 先并行生成候选场景再全局编排，解决贪心生成的叙事断裂。代价是延迟约为直接生成的三倍。</p><p><strong>1 句版</strong>：有些视频应该被编译出来，而不是被采样出来。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>论文反复声称 DVSpec「mechanistically ensure data fidelity and provenance」。这句话里藏着一个偷换：<strong>绑定保证的是渲染的可追溯性，而不是数值的正确性。</strong></p><p>数据本身来自 Data Manager 自动生成并执行的 Python 代码。如果这段代码用错了 groupby 的键、漏了一个过滤条件、或者静默丢弃了空值，DVSpec 会<strong>忠实地</strong>把图表绑定到一个真实存在但计算错误的数据切片上。此时溯源功能不但没有拦住错误，反而给它盖了章——用户点开图表，看到的是货真价实的字段绑定和真实的表记录，结论却是错的。相比像素级模型的数值幻觉，这种失败<strong>更难被发现</strong>，因为它带着一条看起来完整的证据链。</p><p>论文提供的防护只有一条：代码执行失败时的重试策略。重试能接住崩溃，接不住算错。而评测的五个维度（意图达成、数据洞察、叙事质量、动画有效性、美学质量）由 Gemini-2.5-Pro 按主观量表打分，<strong>没有任何一项针对分析正确性</strong>——没有把视频里声称的统计量与真值答案做核对。DAComp-DA 与 T2R-bench 本身是带答案的基准，做这个核对在技术上完全可行，论文却没有报。这是全文最需要补的一个数，也是「保真度」这个核心 claim 唯一的支点。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，重点是把论文缺失的那个度量补上。</p><ul><li><strong>数据</strong>：T2R-bench 里取 20 个样本（自带真值答案）。</li><li><strong>实现</strong>：写一份精简 DVSpec——场景列表，每个场景含图表规格、旁白段列表、以旁白索引触发的动画列表；渲染用 Vega-Lite + 任意 TTS + ffmpeg 拼接。生成侧只用<strong>单个 LLM 一次调用</strong>填规范，带一个 Python 执行工具做聚合，不实现 Story Planner 也不实现 Orchestrator。</li><li><strong>测量</strong>：(a) 执行成功率（对照论文的 48–86% 与 95%）；(b) <strong>分析正确性</strong>——把每个场景里声称的统计量独立重算一遍，检查是否与视频里的数字一致、以及是否与基准的真值答案一致。</li><li><strong>判据</strong>：若单 agent + DVSpec + 渲染器的执行率已经明显跨过 90%，说明执行率的提升主要来自结构化规范与确定性渲染，而非多 agent 架构。若分析正确性在完整溯源可用的情况下仍然偏低，§9 的担忧被证实，「结构性保真」这个说法需要限定为「渲染层保真」。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>基线设定得太弱，导致贡献归因可能整体偏移。</strong></p><p>论文的对照是让四个 LLM「直接一次性生成数据视频」。在这个设定下，基线既没有声明式 schema、没有确定性渲染器、也没有代码执行与重试。任何配备了渲染基础设施的流水线都会靠构造赢——这场比较度量的主要是「有没有编译器」，不是「有没有多 agent」。</p><p><strong>更公平的对照设计</strong>：给基线 LLM <strong>同一份 DVSpec schema、同一套 D3/Remotion 渲染器、同一个 Python 执行工具</strong>，只是不给 Story Planner 与 Orchestrator，让它在单 agent 循环里带重试地填完规范。如果这个版本就能补上 1.91→3.89 的大部分差距，那么论文的核心贡献应被重新表述为<strong>声明式规范 + 确定性渲染管线</strong>（工程），多 agent 分解是次要的第二贡献。</p><p><strong>论文自己的消融数字就指向这个方向</strong>：去掉 Story Planner 后 3.89 降约 11.6%（约 3.44），去掉 Orchestration 降约 9.0%（约 3.54），两者都仍远高于基线的 2.22。也就是说，从 2.22 到 3.89 这段距离里，两个 agent 组件各自只解释了 0.35–0.45，剩下的一大截由 DVSpec 与渲染管线承担。这个替代解释不需要新实验就已经有相当支持，只需要把消融行和基线行放进同一张表比较。</p><p>第二个可预测失败：评审模型 Gemini-2.5-Pro 同时也是被评的四个基线之一，论文没有说明 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.91</span></span></span></span> 的那 60 支采样视频是否在各系统间均衡分布，也没有说明评审是否对系统身份盲。这不必然构成偏差，但在只有一个自动评审的情况下，是需要交代的。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：DVSpec 保证了「这个柱子对应哪些行」，但没有保证「旁白说的这句话是这些行的正确结论」。旁白由 LLM 与图表<strong>并列生成</strong>，而不是从查询结果<strong>派生</strong>——这正是 §9 那个缺口的结构性来源。</p><p><strong>新 framing</strong>：把数据视频当作<strong>可验证的查询程序</strong>而非可编辑的规范。一支数据视频本质上是一串断言，每条断言都是对表的一次查询。与其信任 LLM 手写的 pandas 再让它另写一句旁白，不如把每句旁白编译成可检查的关系代数/SQL 查询，执行之后让旁白文本与图表<strong>都从查询结果派生出来</strong>。这带来两个当前拿不到的性质：断言级的事实可验证性；以及数据更新时视频可以像物化视图一样<strong>增量重编译</strong>，而不是重新生成。</p><p><strong>可借鉴的邻域工具</strong>：NL2SQL 的执行一致性验证（用执行结果而非字符串匹配判正确）、语义解析里的 execution-guided decoding，以及数据库的视图维护与增量计算——它们解决的正是「自然语言断言如何被绑定到可执行、可重算的查询」这个同构问题。</p><p><strong>第一个实验</strong>：在 DAComp-DA 上对比两条流水线——(a) 论文的「LLM 写 pandas + LLM 写旁白」；(b) 「LLM 写 SQL + 旁白从执行结果模板化生成」。度量两项：断言级事实准确率（对照基准真值），以及人评的旁白自然度。核心问题是保真度的提升要付出多少叙事质量的代价。若 (b) 在事实准确率上大幅领先而自然度只略降，说明当前把旁白与查询并列生成是一个可以直接修掉的设计缺陷。</p>',57)])])}const d=s(r,[["render",p]]);export{h as __pageData,d as default};
